package com.tarapickle.identity.infrastructure.email; import com.tarapickle.identity.application.port.EmailPort; import lombok.extern.slf4j.Slf4j; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component;
@Component @Profile("!local") @Slf4j public class LoggingEmailAdapter implements EmailPort { public void sendVerification(String email,String token){log.info("Verification email queued recipientDomain={}",domain(email));} public void sendPasswordReset(String email,String token){log.info("Password-reset email queued recipientDomain={}",domain(email));} private String domain(String e){int i=e.indexOf('@');return i<0?"invalid":e.substring(i+1);} }
